import{_ as t,o as r,c as o,a3 as i}from"./chunks/framework.BZKbe9n2.js";const u=JSON.parse('{"title":"Source service API","description":"","frontmatter":{},"headers":[],"relativePath":"source-api/index.md","filePath":"source-api/index.md"}'),s={name:"source-api/index.md"};function a(c,e,n,h,l,d){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="source-service-api" tabindex="-1">Source service API <a class="header-anchor" href="#source-service-api" aria-label="Permalink to &quot;Source service API&quot;">​</a></h1><p>Anthology acquires music from other sources through <strong>source services</strong>: separate containers that each wrap one source and speak a small HTTP/JSON interface. The core never contains download code for commercial services; a source service can have its own license and its own release cycle.</p><p>This part is for developers who want to write a source service.</p><h2 id="how-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#how-it-fits-together" aria-label="Permalink to &quot;How it fits together&quot;">​</a></h2><ol><li>The server lists the services in <code>ANTHOLOGY_SOURCE_SERVICES</code> and checks each one every minute (<code>GET /v1/info</code>, <code>GET /v1/health</code>).</li><li>Users search a service or paste a link; the server passes the request on (<code>/v1/search</code>, <code>/v1/resolve</code>) and shows the results with what the library already has.</li><li>An order becomes a download task at the service. The service writes the files into the shared imports volume, and the server imports them with its normal import – the service never touches the library.</li></ol><h2 id="writing-a-service" tabindex="-1">Writing a service <a class="header-anchor" href="#writing-a-service" aria-label="Permalink to &quot;Writing a service&quot;">​</a></h2><ul><li>Implement the endpoints of the <a href="./reference">interface reference</a> for interface version 1.</li><li>Take <code>tools/fake-source-service/</code> of the repository as a reference: it speaks every endpoint and is what the end-to-end tests use.</li><li>Respect the terms, rate limits and robots.txt of your source; report rate limits with <code>rate_limited</code> and <code>retry_after</code>.</li><li>Publish the container as a plain OCI image; it runs in the Anthology pod, on one of the ports 8420–8429.</li><li>Choose your service&#39;s license freely. The interface is the only connection to Anthology.</li></ul><p>When the interface changes incompatibly, it gets a new version (<code>/v2</code>); a service with another version is shown as incompatible and left out.</p>',8)])])}const v=t(s,[["render",a]]);export{u as __pageData,v as default};
